Recall that $c_0\in \RR$ and $	heta>1$ are fixed, $x_0\gg 1$ is to be taken large enough and $\qz$ is the solution of  e \partial_t \qz + \partial_x(\partial_x^2 \qz + \qz^5)=0,\quad \qz(0,x)= f_0(x), \ee where the function $f_0$ is smooth and satisfies  e f_0(x)= c_0 x^{-	heta} \hbox{ for $x> rac {x_0}2$},\quad f_0(x)=0 \hbox{ for $x< rac {x_0}4$}, \ee  e \hbox{ for all $x\in \RR$, for all $k\geq 0$},\quad \left| rac {d^{k}f_0}{dx^k} (x)ight| \lesssim c_0 |x|^{-	heta - k}. \ee First, for $x_0$ large enough, $\|f_0\|_{L^2}$ is small and it follows from the $L^2$ and $H^s$ Cauchy theory (Corollary 2.9 in \cite{KPV}) that $q_0$ is global and bounded in $H^s$ for all $s\geq 0$, with $$\sup_t\|q_0(t)\|_{H^s}\lesssim \delta(x_0^{-1}).$$ We define $$ \qu(t,x) = \qz(t,x) -f_0(x), $$  e \partial_t \qu + \partial_x(\partial_x^2 \qu + (\qu+f_0)^5-f_0^5)=F_0,\quad \qu(0,x)= 0, \ee where $$ F_0 = -\partial_x^3 f_0 - \partial_x(f_0^5). $$ For any $ ar 	heta\geq 0$, define a smooth function $\varphi_{ ar 	heta}$ such that  egin{equation} \varphi_{ ar 	heta}(x) = x^{ ar 	heta} 	ext{ for $x\geq 4$},\quad \varphi_{ ar 	heta}(x) = e^{ rac x8} 	ext{ for $x\leq 0$},\quad \varphi'\geq 0,\ \varphi'''\leq  rac 14 \varphi' 	ext{ on $\RR$}. \end{equation} For $$ 0\leq 	heta_1< 2 	heta+4, \quad 	heta_1 
eq 2 	heta+3, $$ set  egin{align*} M_{	heta_1}(t)& = \int q_1^2(t) \varphi_{	heta_1}\left( x -  rac t 4 -  rac {x_0} 4ight) dx, \ E_{	heta_1}(t) &= \int \left( (\partial_x q_1)^2(t) - rac 13 \left( (q_1+f_0)^6 - f_0^6 - 6 q_1 f_0^5ight) ight)\varphi_{	heta_1+2}\left( x -  rac t 4 -  rac {x_0} 4 ight) dx,\\ F_{	heta_1,k}(t) &= \int (\partial_x^k q_1)^2(t) \varphi_{	heta_1+2k}\left( x -  rac t 4 -  rac {x_0} 4ight) dx, \ k\geq 2. \end{align*} We differentiate $M_{	heta_1}(t)$ (omitting the variable $x -  rac t 4 -  rac {x_0} 4$ for the function $\varphi_{	heta_1}$):  egin{align*} M_{	heta_1}'(t) & = - 3 \int (\partial_x q_1)^2 \varphi_{	heta_1}' - rac 14 \int q_1^2 \varphi_{	heta_1}' + \int q_1^2 \varphi_{	heta_1}''' \ & + 2 \int \left((q_1+f_0)^5 - f_0^5ight) (q_1 \varphi_{	heta_1})_x + 2 \left|\int F_0 q_1 \varphi_{	heta_1} ight|\ & \leq - 3 \int (\partial_x q_1)^2 \varphi_{	heta_1}' - rac 3{16} \int q_1^2 \varphi_{	heta_1}' - 2 \int \left[  rac {(q_1+f_0)^6}6 -  rac {f_0^6} 6-(q_1+f_0)^5 q_1ight] \varphi_{	heta_1}' \ & + 2 \int \left[ (q_1+f_0)^5 - 5 q_1^4 f_0-f_0^5ight] f_0' \varphi_{	heta_1} + 2 \left|\int F_0^2  rac {\varphi_{	heta_1}^2}{\varphi_{	heta_1}'} ight|^{ rac 12} \left| \int q_1^2 \varphi_{	heta_1}'ight|^{ rac 12} \ & \leq - 3 \int (\partial_x q_1)^2 \varphi_{	heta_1}' - rac 1 8 \int q_1^2 \varphi_{	heta_1}' +\delta(x_0^{-1}) \int q_1^2 \varphi_{	heta_1}' + C \int F_0^2  rac {\varphi_{	heta_1}^2}{\varphi_{	heta_1}'} . \end{align*} Thus, for $x_0$ large enough, we have obtained $$ M_{	heta_1}'(t) +  rac 1{10} \int \left[ (\partial_x q_1)^2 + q_1^2 ight] \varphi_{	heta_1}' \lesssim \int F_0^2  rac {\varphi_{	heta_1}^2}{\varphi_{	heta_1}'} . $$ For $x_0$ large enough,  egin{align} \int F_0^2  rac {\varphi_{	heta_1}^2} {\varphi_{	heta_1}'}\left( x -  rac t 4 -  rac {x_0} 4ight) & \lesssim \int_{x> rac t4 +  rac {x_0} 4 + 4} x^{-2(	heta+3)} \left( x -  rac t 4 -  rac {x_0} 4 ight)^{	heta_1+1} 
onumber \ & + \int_{ rac t8 +  rac {x_0} 8 < x< rac t4 +  rac {x_0} 4 + 4} x^{-2(	heta+3)} +\int_{x<  rac t8 +  rac {x_0} 8} e^{ rac 18 (x- rac t 4 -  rac {x_0} 4 )}
onumber \ & \lesssim (t+x_0)^{ 	heta_1 -2 	heta-4 } . \end{align} Therefore, using also $M_{	heta_1}(0)=0$, we find by integration:  e M_{	heta_1}(t) + \int_0^t\int \left[ (\partial_x q_1)^2 + q_1^2 ight] \varphi_{	heta_1}' \lesssim  egin{cases} (t+x_0)^{ 	heta_1 -2 	heta-3 } & \hbox{if $0<	heta_1 {-}2 	heta{-}3<1$} \ x_0^{ 	heta_1 -2 	heta-3 } & \hbox{if $	heta_1 {-}2 	heta{-}3<0$} \end{cases} \ee We argue similarly for $E_{	heta_1}(t)$.  egin{align*} E_{	heta_1}'(t) & = 2 \int \partial_t q_1 \left[ - \partial_x^2 q_1 - \left((q_1+f_0)^5 - f_0^5ight)ight] \varphi_{	heta_1+2}\ & - 2 \int \partial_t q_1 \partial_x q_1 \varphi_{	heta_1+2}' -  rac 14 \int\left[ (\partial_x q_1)^2(t) - rac 13 \left( (q_1+f_0)^6 - f_0^6 - 6 q_1 f_0^5ight) ight]\varphi_{	heta_1+2}' \ &= - \int \left[ \partial_x^2 q_1 + \left((q_1+f_0)^5 - f_0^5ight) ight]^2 \varphi_{	heta_1+2}'\ & - 2 \int \left[ \partial_x^2 q_1 + (q_1 + f_0)^5 - f_0^5ight] F_0\varphi_{	heta_1+2}\ & + 2 \int \left[ \partial_x^2 q_1 + (q_1 + f_0)^5 - f_0^5ight]_x \partial_x q_1 \varphi_{	heta_1+2}' - 2 \int F_0 \partial_x q_1 \varphi_{	heta_1+2}' \ &-  rac 14 \int\left[ (\partial_x q_1)^2(t) - rac 13 \left( (q_1+f_0)^6 - f_0^6 - 6 q_1 f_0^5ight) ight]\varphi_{	heta_1+2}'. \end{align*} We use the following computations and estimates  egin{align*} &\left| \int \left[ \partial_x^2 q_1 + (q_1 + f_0)^5 - f_0^5ight] F_0\varphi_{	heta_1+2} ight| \ & \lesssim \left| \int \partial_x q_1 (F_0 \varphi_{	heta_1+2})_x ight| + \left| \int \left[ (q_1 + f_0)^5 - f_0^5ight] F_0\varphi_{	heta_1+2}ight| \ & \lesssim  rac 1{100} \int (\partial_x q_1)^2 \varphi_{	heta_1+2}' + rac 1{100} \int q_1^2 \varphi_{	heta_1}' \ & + C \int \left(|\partial_x F_0|^2  rac {\varphi_{	heta_1+2}^2}{\varphi_{	heta_1+2}'} + |F_0|^2 \varphi_{	heta_1+2}' + |F_0|^2  rac {f_0^8 \varphi_{	heta_1+2}^2}{\varphi_{	heta_1}'}ight). \end{align*}  egin{align*} 2 \int \partial_x^3 q_1 \partial_x q_1 \varphi_{	heta_1+2}' & = - 2 \int (\partial_x^2 q_1)^2 \varphi_{	heta_1+2}' + \int (\partial_x q_1)^2 \varphi_{	heta_1+2}'''\ & \leq - 2 \int (\partial_x^2 q_1)^2 \varphi_{	heta_1+2}' +  rac 14 \int (\partial_x q_1)^2 \varphi_{	heta_1+2}'. \end{align*}  egin{align*} & \left| 2 \int \left[ (q_1+f_0)^5 - f_0^5ight]_x \partial_x q_1 \varphi_{	heta_1+2}' ight|\ & =\left| 10 \int (\partial_x q_1)^2 (q_1+f_0)^4 \varphi_{	heta_1+2}' +10 \int \left( (q_1+f_0)^4 - f_0^4ight) \partial_x f_0 \partial_x q_1 \varphi_{	heta_1+2}'ight|\ & \leq  rac 1{100} \int (\partial_x q_1)^2 \varphi_{	heta_1+1}' + C \int q_1^2 \varphi_{	heta_1}'. \end{align*}  egin{align*} 2 \left| \int F_0 \partial_x q_1 \varphi_{	heta_1+2}'ight| \leq  rac 1{100} \int (\partial_x q_1)^2 \varphi_{	heta_1+1}' + C \int |F_0|^2\varphi_{	heta_1+2}'. \end{align*} Combining these estimates, and using the expression of $F_0$ as in \eqref{Fzero}, we find  egin{align*} E_{	heta_1}'(t) \leq - \int (\partial_x^2 q_1)^2 \varphi_{	heta_1+2}' -  rac 1{10} \int (\partial_x q_1)^2 \varphi_{	heta_1+2}' + C\int q_1^2 \varphi_{	heta_1}' + C (t+x_0)^{ 	heta_1 -2 	heta-4 }. \end{align*} By integration, and using \eqref{eqM},  egin{align} & E_{	heta_1}(t) +  rac 1{10} \int_0^t \int \left[(\partial_x^2 q_1)^2 + (\partial_x q_1)^2 ight]\varphi_{	heta_1+2}'
onumber \ & \lesssim  egin{cases} (t+x_0)^{ 	heta_1 -2 	heta-3 } & \hbox{if $0<	heta_1 {-}2 	heta{-}3<1$} \ x_0^{ 	heta_1 -2 	heta-3 } & \hbox{if $	heta_1 {-}2 	heta{-}3<0$} \end{cases} \end{align} We look for an estimate on $\partial_x q_1(t)$ from the above estimate on $E_{	heta_1}(t)$. Note first that  egin{align} \|q_1^2 \sqrt{\varphi_{	heta_1+2}} \|_{L^\infty} &\lesssim \int_x^{+\infty} |q_1| |\partial_x q_1| \sqrt{\varphi_{	heta_1+2}} + \int_x^{+\infty} |q_1|^2  rac {\varphi_{	heta_1+2}'}{\sqrt{\varphi_{	heta_1+2}}}
onumber\ & \lesssim \left( \int q_1^2ight)^{ rac 12} \left( \int |\partial_x q_1|^2 \varphi_{	heta_1+2} + \int |q_1|^2 \varphi_{	heta_1}ight)^{ rac 12}, \end{align} so that  egin{align*} \int q_1^6 \varphi_{	heta_1+2} \leq \|q_1^2 \sqrt{\varphi_{	heta_1+2}} \|_{L^\infty}^2 \int q_1^2 \lesssim \left( \int q_1^2ight)^2 \left( \int |\partial_x q_1|^2 \varphi_{	heta_1+2} + M_{	heta_1}(t)ight) . \end{align*} Also, $$ \int q_1^2 f_0^4 \varphi_{	heta_1+2} \lesssim \int q_1^2 \varphi_{	heta_1} = M_{	heta_1}(t). $$ Thus,  egin{align} E_{	heta_1}(t) & \geq \int (\partial_x q_1)^2 \varphi_{	heta_1+2} - C \int (q_1^6 + q_1^2 f_0^4) \varphi_{	heta_1+2}
onumber\ & \geq  rac 12 \int (\partial_x q_1)^2 \varphi_{	heta_1+2} - C M_{	heta_1}(t), \end{align} and so  egin{align} &\int (\partial_x q_1)^2 \varphi_{	heta_1+2}+ \int_0^t \int \left[(\partial_x^2 q_1)^2 + (\partial_x q_1)^2 ight]\varphi_{	heta_1+2}'
